 if(p>=0){/* Edge-inset UVs, mirrored horizontal repeats and feathered row overlaps. */float speed=k==ENV_OCEAN?35:70,scroll=fmodf(backgroundClock*speed,696),tw,th;SDL_GetTextureSize(journeyPlates,&tw,&th);float angle=flight_view_angle(),fieldW=960-264*sideBlend,cover=fmaxf(1,(960*fabsf(cosf(angle))+696*fabsf(sinf(angle)))/fieldW)*1.04f,tileW=960*cover,z=ex.giant.active?journeyZoom:1;float u=(p%3)/3.0f+4/tw,vv=(p/3)/2.0f+4/th,uw=1/3.0f-8/tw,vh=1/2.0f-8/th;int span=ex.giant.active?2:0;for(int col=-span;col<=span;col++)for(int n=-2;n<=2;n++){float y=72+scroll+n*696,x=480-tileW/2+col*tileW,uu=u,du=uw;if(abs(col)&1){uu+=du;du=-du;}nquad=0;quad(x,y,tileW,72,(SDL_FColor){.7f,.75f,.8f,1},uu,vv,du,vh*72/768);vertices[0].color.a=vertices[1].color.a=0;quad(x,y+72,tileW,696,(SDL_FColor){.7f,.75f,.8f,1},uu,vv+vh*72/768,du,vh*696/768);float w=(960-264*sideBlend)*z,h=(696+264*sideBlend)*z;for(int v=0;v<nquad*4;v++){float xx=(vertices[v].position.x-480)*w/960,yy=(vertices[v].position.y-420)*h/696;vertices[v].position.x=480+xx*cosf(angle)-yy*sinf(angle);vertices[v].position.y=420+xx*sinf(angle)+yy*cosf(angle);}lastGroundDX=-sinf(angle)*backgroundClock*speed*h/696;lastGroundDY=cosf(angle)*backgroundClock*speed*h/696;flush(journeyPlates);}}
